(function (root) {
  "use strict";

  const data = root.S005_FULL_CHAIN_DATA;
  const esc = (value) => String(value ?? "").replace(/[&<>"']/g, (char) => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" }[char]));
  const badge = (label, tone = "") => `<span class="s005-baseline-badge ${tone}">${esc(label)}</span>`;
  const statusTone = (status) => status === "complete" ? "success" : status === "running" ? "info" : status === "blocked" ? "danger" : "";
  const stageLabels = { M02: "数据工程", M01: "分类与语义", M03: "市场与合规", M04: "池内选择", M05: "交易与风险", M06: "报告中心" };
  const inlineTrend = (series) => {
    const width = 700; const height = 230; const pad = 42; const values = series.flatMap((item) => item.values.map(Number)); const min = Math.min(...values); const max = Math.max(...values); const span = max - min || 1;
    const x = (index, count) => pad + index * (width - pad - 24) / Math.max(1, count - 1); const y = (value) => height - 35 - ((Number(value) - min) / span) * (height - 70);
    const path = (values) => values.map((value, index) => `${index ? "L" : "M"}${x(index, values.length).toFixed(1)},${y(value).toFixed(1)}`).join(" ");
    return `<div class="s005-baseline-chart"><svg viewBox="0 0 ${width} ${height}" role="img" aria-label="市场同类净值趋势"><g class="s005-grid-lines"><line x1="${pad}" x2="${width - 24}" y1="${y(min)}" y2="${y(min)}"></line><line x1="${pad}" x2="${width - 24}" y1="${y((min + max) / 2)}" y2="${y((min + max) / 2)}"></line><line x1="${pad}" x2="${width - 24}" y1="${y(max)}" y2="${y(max)}"></line></g>${series.map((item) => `<path d="${path(item.values)}" stroke="${esc(item.color)}"></path>`).join("")}<g class="s005-axis-label"><text x="8" y="${y(max) + 4}">${max.toFixed(1)}</text><text x="8" y="${y((min + max) / 2) + 4}">${((min + max) / 2).toFixed(1)}</text><text x="8" y="${y(min) + 4}">${min.toFixed(1)}</text></g></svg></div>`;
  };
  const legend = (series) => `<div class="s005-baseline-legend">${series.map((item) => `<span><i style="background:${esc(item.color)}"></i>${esc(item.label)}</span>`).join("")}</div>`;

  function context(args) { return args.STORE.getScenarioContext?.() || args.STORE.get?.()?.scenarioContext || {}; }
  function projection(args) { return args.STORE.getProjection?.() || { steps: {}, completeCount: 0, total: 7 }; }
  function research() { return root.OFW_S005_RUNNER?.state?.() || { status: "待运行", running: false, events: [] }; }
  function stageProgress(args) {
    const p = projection(args); return args.DATA.workflow.map((step) => ({ ...step, record: p.steps?.[step.id] || {} }));
  }

  function homeContent(args) {
    const RD = args.RESEARCH || root.S005_FULL_CHAIN_DATA; const p = projection(args); const r = research(); const done = p.completeCount || 0; const total = p.total || args.DATA.workflow.length; const percent = Math.round(done / Math.max(1, total) * 100); const next = args.STORE.firstIncomplete?.();
    const stages = stageProgress(args);
    return `<div class="home-view s005-baseline-home"><div class="home-container">
      <section class="home-status-strip s005-status-strip"><div class="scenario-identity"><span>S005 研究运行档案</span><strong>金融产品投后评价全周期闭环</strong><small>${esc(RD.meta.asOf)} · ${esc(RD.meta.formulaVersion)} · 活动基线 v1.1.0</small></div><div class="scenario-progress"><div><span>研究链完成度</span><b>${done}/${total}</b></div><i><i style="width:${percent}%"></i></i><small>${r.status === "研究草稿" ? "研究草稿已形成" : r.running ? "研究链路运行中" : "等待运行"}</small></div><div class="scenario-next"><span>当前上下文</span><strong>${esc(context(args).scenarioRunId || "")}</strong><small>治理父版本 v1.0.3 仅作历史回退；不写入正式生产资源。</small></div><button class="btn primary" type="button" data-action="s005-run-chain">${r.running ? "运行中" : "运行 S005 研究链路"}${args.icon("arrow", "sm")}</button></section>
      <section class="s005-baseline-overview"><div class="s005-overview-head"><div><span class="s005-overline">S005 · v1.1.0 基线注入</span><h1>投后评价从来源到研究草稿</h1><p>统一工作台只负责场景、路由、状态和证据边界；每个阶段由对应的基线模块入口承接。</p></div><div class="s005-baseline-chip">${badge("研究夹具", "warning")}<span>79 份周期间快照</span></div></div><div class="s005-stage-track" aria-label="S005 研究阶段">${stages.map((step, index) => `<button type="button" data-route="#module/${args.DATA.moduleById[step.module].id}" class="${statusTone(step.record.status)}"><span>${String(index + 1).padStart(2, "0")}</span><strong>${esc(step.title)}</strong><small>${esc(step.record.status === "complete" ? "已完成" : step.record.status === "running" ? "运行中" : "待运行")}</small></button>`).join("")}</div><div class="s005-domain-grid"><article><span>产品自身表现</span><strong>TWR · 基准超额 · 同类位置</strong><small>市场横评模块</small></article><article><span>财务公司实际结果</span><strong>MWR · 现金流 · 已实现 / 未实现</strong><small>交易与风险模块</small></article><article><span>固定收益风险</span><strong>久期 · 集中度 · 流动性 · 归因</strong><small>独立风险灯</small></article><article><span>管理与运行质量</span><strong>合规 · 披露 · 估值 · 重大事件</strong><small>持续观察</small></article></div></section>
      <div class="s005-baseline-grid"><section class="panel"><div class="panel-head"><div><h2>当前研究状态</h2><p>状态来自 S005 adapter projection，不由页面推断。</p></div>${badge(r.status, r.status === "研究草稿" ? "success" : "warning")}</div><div class="s005-home-kpis">${RD.kpis?.map((metric) => `<div><span>${esc(metric.label)}</span><strong>${esc(metric.value)} <em>${esc(metric.unit)}</em></strong></div>`).join("") || RD.trading.metrics.slice(0, 6).map((metric) => `<div><span>${esc(metric.label)}</span><strong>${esc(metric.value)}</strong></div>`).join("")}</div><div class="s005-next-step"><span>下一阶段</span><strong>${next ? esc(next.title) : "全部阶段已形成研究输出"}</strong><small>${next ? esc(next.summary) : "可进入报告中心查看证据链和部分评价说明。"}</small></div></section><section class="panel"><div class="panel-head"><div><h2>模块 Owner 与边界</h2><p>沿用 M01—M06 基线路由，研究结果只读消费。</p></div></div><div class="s005-owner-list">${args.DATA.modules.map((module) => `<button type="button" data-route="#module/${module.id}" class="s005-owner-row"><span>${esc(module.id.toUpperCase())}</span><div><strong>${esc(module.name)}</strong><small>${esc(module.description)}</small></div>${badge(module.id === "M04" || module.id === "M05" ? "只读关联" : "研究输入", module.id === "M04" || module.id === "M05" ? "warning" : "success")}</button>`).join("")}</div></section></div>
      <div class="workspace-note">S005 状态存储在 v1.1.0 Foundation namespaced storage；M04/M05 不创建 Action Request、审批、待办或交易指令。</div>
    </div></div>`;
  }

  function dashboardContent(args) {
    const RD = args.RESEARCH || root.S005_FULL_CHAIN_DATA; const r = research(); const p = projection(args); const market = RD.market; const selection = RD.selection;
    return `<div class="dashboard-view s005-baseline-dashboard"><div class="s005-dashboard-wrap"><header class="dashboard-head"><div><span class="s005-overline">S005 · 报告中心 / 仪表盘消费</span><h1>投后评价研究驾驶舱</h1><p>基于当前 S005 运行轮次的高密度结果视图，所有状态和证据均沿 v1.1.0 场景上下文回链。</p></div><div class="dashboard-head-actions"><button class="btn" type="button" data-action="s005-run-chain">${r.running ? "运行中" : "运行研究链路"}</button><button class="btn" type="button" data-action="open-flow">${args.icon("layers", "sm")}运行档案</button></div></header><section class="s005-dashboard-facts"><div><span>活动基线</span><strong>v1.1.0</strong><small>BSL-OFW-V110-94ABD0E991B7</small></div><div><span>运行轮次</span><strong>${esc(args.STORE.getScenarioContext?.().scenarioRunId || "")}</strong><small>ofw:v1.1.0:S005 命名空间</small></div><div><span>数据截至</span><strong>${esc(RD.meta.asOf)}</strong><small>周期间快照 + Wind 夹具</small></div><div><span>结论状态</span><strong>${esc(r.status === "研究草稿" ? "部分评价" : "待运行")}</strong><small>不等同于验收或正式发布</small></div></section><div class="metrics-grid s005-dashboard-metrics">${(RD.kpis || RD.trading.metrics.slice(0, 6)).map((metric) => `<article class="metric"><span>${esc(metric.label)}</span><div class="metric-value"><strong>${esc(metric.value)}</strong><em>${esc(metric.unit || "")}</em></div><small>研究夹具 · 可回链证据</small></article>`).join("")}</div><div class="grid-main s005-dashboard-grid"><section class="panel"><div class="panel-head"><div><h2>市场同类净值趋势</h2><p>入池、同类中位数、前三分之一、合同基准和实际交易子集</p></div>${badge("Wind 待接入", "warning")}</div><div class="panel-body">${legend(market.series)}${inlineTrend(market.series)}<p class="s005-caption">同类样本 ${market.sampleCount} 只 · 纳入 ${market.included} 只 · 评价日 ${market.asOf}</p></div></section><section class="panel"><div class="panel-head"><div><h2>独立风险灯</h2><p>风险不被收益评分抵销</p></div></div><div class="panel-body"><div class="s005-risk-list">${RD.riskLamps.map((lamp) => `<div class="${lamp.tone}"><span>${esc(lamp.label)}</span><strong>${esc(lamp.value)}</strong><small>${esc(lamp.detail)}</small></div>`).join("")}</div></div></section></div><div class="grid-main s005-dashboard-grid"><section class="panel"><div class="panel-head"><div><h2>选中 vs 池内未选</h2><p>冻结决策后的 T+1 / T+5 / T+20 / T+60</p></div><button class="text-btn" type="button" data-route="#module/decision">进入池内选择</button></div><div class="panel-body">${legend(selection.series)}${inlineTrend(selection.series)}<p class="s005-caption">T+60 选择差异 ${esc(selection.spread)} · ${esc(selection.confidence)}</p></div></section><section class="panel"><div class="panel-head"><div><h2>证据链状态</h2><p>来源 → 分类 → 评价 → 研究草稿</p></div></div><div class="panel-body"><div class="s005-evidence-chain">${args.DATA.workflow.map((step, index) => `<div><b>${String(index + 1).padStart(2, "0")}</b><span>${esc(step.title)}</span>${badge(p.steps?.[step.id]?.complete ? "已完成" : "待运行", p.steps?.[step.id]?.complete ? "success" : "warning")}</div>`).join("")}</div></div></section></div><section class="panel"><div class="panel-head"><div><h2>研究边界</h2><p>沿用 v1.1.0 报告和行动边界，当前不生成生产资源</p></div></div><div class="panel-body"><div class="s005-boundary-grid"><div><span>允许范围</span><strong>利率债、短期纯债、中长期纯债、混合一级、混合二级</strong></div><div><span>可计算指标</span><strong>TWR、MWR、夏普、Sortino、Calmar、信息比率、回撤、归因</strong></div><div><span>待补数据</span><strong>Wind 日 NAV、现金流、穿透持仓、主体映射、事件回溯</strong></div><div><span>禁用动作</span><strong>Published、Action Request、提醒、审批、待办、交易指令</strong></div></div></div></section></div></div>`;
  }

  root.S005_BASELINE_VIEW = Object.freeze({ homeContent, dashboardContent });
})(typeof window !== "undefined" ? window : globalThis);
